export const millFilmCaptions=Object.freeze([{"start": 0.2, "end": 2.2, "text": "An overshot wheel: the water arrives at the top."}, {"start": 2.2, "end": 4.4, "text": "Follow one bucketful high in the chute."}, {"start": 4.4, "end": 7.0, "text": "High water and Earth have a gravitational store."}, {"start": 7.2, "end": 9.4, "text": "It pours into a bucket at the top of the wheel."}, {"start": 9.4, "end": 12.2, "text": "Its weight pulls that side down, helping the wheel turn."}, {"start": 12.2, "end": 16.0, "text": "Energy transfers to the turning wheel: a kinetic store."}, {"start": 16.2, "end": 19.0, "text": "The axle turns the millstone, and it grinds the grain."}, {"start": 19.0, "end": 21.5, "text": "Grinding and rubbing warm the stones, the flour and the air."}, {"start": 21.5, "end": 24.0, "text": "Moving energy spreads into thermal stores."}, {"start": 24.2, "end": 26.8, "text": "The tracked energy was not destroyed. It spread out."}, {"start": 26.8, "end": 29.4, "text": "Spread-out warmth is hard to use again."}, {"start": 29.4, "end": 32.0, "text": "Sunlight drives evaporation. Rain feeds high streams."}].map(Object.freeze));
const intro="Follow the energy from one bucketful in a mill that keeps running. Other water keeps its wheel turning. Your table follows a separate batch; its amounts and pictures do not match this film one for one.", explanation="Your requests and kept picture will wait. Pause, replay, or read the complete words below. Return to find your table as you left it.", about=["This is a supplied explanatory sketch, not a measured experiment or a mill construction plan. Our followed bucket tips to show its water pouring into the lower channel; the other drawn buckets are simplified. The water flows on; it does not turn into energy.", "The jars follow an energy contribution from one bucketful, not the whole mill. Energy has no labels, so we cannot point to “our” energy inside the wheel. The jars show an amount equal to what our bucketful transfers. While the mill runs steadily, the wheel’s speed and its kinetic store stay about the same: energy passes through the moving wheel to the stones about as fast as buckets supply it. The jars stretch these steps out so we can follow them. Their heights are an invented account, not measured amounts, water levels, wheel speed or efficiency. Other water keeps supplying the wheel after our moving column empties. Your table instead follows a separate finite batch and stops its wheel when that batch's moving store empties. Neither drawing counts all the energy already in the room or Earth.", "Some energy warms the axle and other rubbing parts before reaching the stones. Grinding also warms stones, flour and nearby air. This warming does not give flour its chemical food energy; the growing plant captured that energy from sunlight. Spread-out warmth does not set this wheel turning again by itself.", "Sun-warmed water evaporates. Water vapor condenses into clouds and can fall as rain on high ground. Water collecting in high streams can then flow downhill. The Sun does not lift liquid straight into the mill's chute. This is a short water-cycle connection, not a complete explanation of weather."], credit="A corrected After the Storm film made with Claude Motion. Andika lettering, SIL Open Font License 1.1.";
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(action,label,disabled=false)=>`<button type="button" data-mill-film-action="${action}"${disabled?' disabled':''}>${esc(label)}</button>`;
let millFilmCleanup=null,millFilmPause=null;
export function pauseMillFilm(){millFilmPause?.();}
export function stopMillFilm(){millFilmCleanup?.();millFilmCleanup=null;millFilmPause=null;}
export function millFilmEntry(){return `<button type="button" class="me-film-invitation" data-energy-action="watch"><span>Watch the mill film<small>Optional silent film · 32 seconds</small></span></button>`;}
export function millFilmPage(){return `<section class="me-movie" data-mill-film-movie><div class="me-film-heading"><h2>The mill wheel: where the energy goes</h2><button type="button" data-mill-film-return>Return to my mill</button></div><p>${esc(intro)}</p><p>${esc(explanation)}</p><video controls playsinline muted preload="none" tabindex="0" poster="./assets/mill-energy-corrected.jpg" aria-label="The mill wheel: where the energy goes, silent corrected film" aria-describedby="mill-film-caption"></video><p id="mill-film-caption" class="me-film-caption" data-mill-film-caption>Read the complete transcript below at any time.</p><div class="me-film-controls">${button('play','Play',true)}${button('replay','Replay',true)}${button('retry','Retry loading')}</div><p data-mill-film-load-status role="status"></p><details data-mill-film-transcript><summary>Read the complete film transcript</summary><ol>${millFilmCaptions.map(c=>`<li>${esc(c.text)}</li>`).join('')}</ol></details><details><summary>About these drawings</summary>${about.map(p=>`<p>${esc(p)}</p>`).join('')}</details><p class="me-film-credit">${esc(credit)}</p></section>`;}
export function bindMillFilm(root,live,beforePlay){
 stopMillFilm();const video=root.querySelector('video'),play=root.querySelector('[data-mill-film-action=play]'),replay=root.querySelector('[data-mill-film-action=replay]'),retry=root.querySelector('[data-mill-film-action=retry]'),status=root.querySelector('[data-mill-film-load-status]'),caption=root.querySelector('[data-mill-film-caption]');
 let disposed=false,revision=0,playRevision=0,wanted=false,controller=null,source=null,track=null,playTask=null;const off=[];
 const on=(target,event,fn)=>{target.addEventListener(event,fn);off.push(()=>target.removeEventListener(event,fn));};
 const current=()=>!disposed&&root.isConnected&&live(),active=()=>current()&&!document.hidden;
 const pause=()=>{wanted=false;playRevision++;video.pause();if(current())play.textContent='Play';};millFilmPause=pause;
 const detach=()=>{video.removeAttribute('src');track?.remove();track=null;video.load();if(source){URL.revokeObjectURL(source);source=null;}};
 const failure=()=>{if(current())status.textContent='The film could not play here. Read the transcript or return to your mill.';};
 const updateCaption=()=>{if(current())caption.textContent=(video.ended?millFilmCaptions.at(-1):millFilmCaptions.find(c=>video.currentTime>=c.start&&video.currentTime<c.end))?.text||'\u00a0';};
 const requestPlay=()=>{if(!active()||!source)return;wanted=true;const serial=++playRevision,task={serial,revision};playTask=task;try{Promise.resolve(video.play()).then(()=>{if(playTask!==task)return;playTask=null;if(!active()||!wanted||serial!==playRevision||task.revision!==revision)video.pause();}).catch(e=>{if(playTask===task)playTask=null;if(e?.name!=='AbortError'&&current()&&serial===playRevision&&task.revision===revision){wanted=false;failure();}});}catch{playTask=null;wanted=false;failure();}};
 const load=async auto=>{
  if(!current())return;pause();controller?.abort();const rev=++revision;detach();controller=new AbortController();const signal=controller.signal;play.disabled=true;replay.disabled=true;status.textContent='Loading the mill film…';wanted=auto&&typeof matchMedia==='function'&&!matchMedia('(prefers-reduced-motion: reduce)').matches;const ticket=playRevision;
  try{const response=await fetch('./assets/mill-energy-corrected.mp4',{signal});if(!response.ok)throw Error('Unavailable');const blob=await response.blob();if(!current()||rev!==revision)return;
   source=URL.createObjectURL(new Blob([blob],{type:'video/mp4'}));video.muted=true;video.src=source;track=document.createElement('track');track.kind='captions';track.srclang='en';track.label='English';track.src='./assets/mill-energy-corrected.vtt';video.append(track);track.track.mode='hidden';play.disabled=false;replay.disabled=false;status.textContent='';if(wanted&&ticket===playRevision&&active())requestPlay();
  }catch(e){if(current()&&rev===revision){wanted=false;status.textContent='';if(e?.name!=='AbortError')failure();}}
 };
 on(play,'click',()=>{if(!active()||play.disabled)return;if(video.paused)requestPlay();else pause();});on(replay,'click',()=>{if(!active()||replay.disabled)return;video.currentTime=0;requestPlay();});on(retry,'click',()=>{if(current())void load(false);});
 on(video,'play',()=>{if(!active()||(playTask&&(!wanted||playTask.serial!==playRevision||playTask.revision!==revision))){pause();return;}wanted=true;beforePlay();play.textContent='Pause';});on(video,'pause',()=>{wanted=false;playRevision++;if(current())play.textContent='Play';});on(video,'ended',()=>{wanted=false;updateCaption();});on(video,'timeupdate',updateCaption);on(video,'seeked',updateCaption);on(video,'error',failure);
 on(root.querySelector('[data-mill-film-transcript]'),'toggle',e=>{if(e.target.open&&current())pause();});on(document,'visibilitychange',()=>{if(document.hidden)pause();});on(window,'pagehide',pause);
 millFilmCleanup=()=>{disposed=true;wanted=false;revision++;playRevision++;controller?.abort();off.forEach(fn=>fn());video.pause();detach();};void load(true);
}
